Q: CodeIgniter accessing models from helper A: <p>You can actually do this.</p>

<p>Here's an example</p>

<pre><code>&lt;?php  if ( ! defined('BASEPATH')) exit('No direct script access allowed');

class Example {
    public function __construct()
    {
        $this-&gt;CI =&amp; get_instance();
    }
    public function functionExample(){

        $this-&gt;CI-&gt;load-&gt;module('fullpage');
        if($this-&gt;CI-&gt;fullpage-&gt;my_function() ){
           echo 'It works!'; 
        }
    }
}
</code></pre>
